fn intersperse(numbers: &[i32], delim: i32) -> Vec<i32> {
    let n = numbers.len();
    if n == 0 {
        return Vec::new();
    }
    
    let mut result = Vec::with_capacity(2 * n - 1);
    
    for (i, &num) in numbers.iter().enumerate() {
        if i > 0 {
            result.push(delim);
        }
        result.push(num);
    }
    
    result
}